begin;
create table if not exists public.angelcare_marketplace_operations_missions(
 id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('MIS-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),canonical_mission_id uuid,source_type text not null,source_id uuid,family_account_id uuid references public.angelcare_marketplace_family_accounts(id),organization_id uuid references public.angelcare_marketplace_b2b_organizations(id),b2b_program_id uuid references public.angelcare_marketplace_b2b_programs(id),territory_id uuid,tenant_id uuid references public.angelcare_marketplace_partner_tenants(id),service_type text not null,title text not null,status text not null default 'draft' check(status in('draft','awaiting_authorization','authorized','staffing_required','proposed','assigned','awaiting_acceptance','accepted','brief_acknowledged','travel_ready','check_in_pending','in_progress','incident_open','check_out_pending','report_pending','validation_pending','correction_required','validated','payable_handover','closed','cancelled','suspended')),priority text not null default 'normal' check(priority in('low','normal','high','critical','emergency')),scheduled_start timestamptz not null,scheduled_end timestamptz not null,mission_date date generated always as ((scheduled_start at time zone 'UTC')::date) stored,timezone text not null default 'Africa/Casablanca',location jsonb not null default '{}',operational_zone text,age_group text,required_certifications text[] not null default '{}',required_equipment text[] not null default '{}',owner_id uuid,assigned_provider_id uuid references public.angelcare_marketplace_provider_profiles(id),risk_level text not null default 'normal',next_action text,authorized_at timestamptz,validated_at timestamptz,closed_at timestamptz,late_risk boolean not null default false,overdue_checkout boolean not null default false,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_operations_assignment_proposals(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.angelcare_marketplace_operations_missions(id) on delete cascade,provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id),score int not null check(score between 0 and 100),eligibility_snapshot jsonb not null,availability_snapshot jsonb not null,travel_snapshot jsonb not null,conflicts text[] not null default '{}',status text not null default 'proposed' check(status in('proposed','selected','rejected','expired','cancelled')),proposed_by uuid not null,proposed_at timestamptz not null default now(),decided_by uuid,decided_at timestamptz,decision_reason text,unique(mission_id,provider_id,status));
create table if not exists public.angelcare_marketplace_operations_mission_assignments(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.angelcare_marketplace_operations_missions(id) on delete cascade,provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id),proposal_id uuid references public.angelcare_marketplace_operations_assignment_proposals(id),role_key text not null default 'primary',status text not null default 'awaiting_acceptance' check(status in('awaiting_acceptance','accepted','rejected','cancelled','completed')),assigned_by uuid not null,assigned_at timestamptz not null default now(),accepted_at timestamptz,rejected_at timestamptz,rejection_reason text,backup boolean not null default false,territory_id uuid,tenant_id uuid,unique(mission_id,provider_id,role_key));
create table if not exists public.angelcare_marketplace_operations_mission_briefs(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.angelcare_marketplace_operations_missions(id) on delete cascade,version int not null,purpose text not null,service_limits text[] not null default '{}',instructions jsonb not null default '{}',safeguarding_requirements text[] not null default '{}',emergency_contacts jsonb not null default '[]',required_equipment text[] not null default '{}',reporting_requirements text[] not null default '{}',published_at timestamptz,published_by uuid,created_at timestamptz not null default now(),unique(mission_id,version));
create table if not exists public.angelcare_marketplace_operations_brief_acknowledgements(id uuid primary key default gen_random_uuid(),brief_id uuid not null references public.angelcare_marketplace_operations_mission_briefs(id),mission_id uuid not null references public.angelcare_marketplace_operations_missions(id),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id),brief_version int not null,acknowledged_at timestamptz not null default now(),session_reference text,device_context jsonb not null default '{}',unique(brief_id,provider_id));
create table if not exists public.angelcare_marketplace_operations_check_events(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.angelcare_marketplace_operations_missions(id),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id),event_type text not null check(event_type in('check_in','check_out')),event_at timestamptz not null default now(),evidence_method text not null,location jsonb not null default '{}',device_context jsonb not null default '{}',exception_reason text,reviewed_by uuid,review_status text not null default 'accepted' check(review_status in('accepted','review_required','approved','rejected')),territory_id uuid,tenant_id uuid,unique(mission_id,provider_id,event_type));
create table if not exists public.angelcare_marketplace_operations_checklist_templates(id uuid primary key default gen_random_uuid(),template_key text unique not null,title_fr text not null,service_type text,age_group text,territory_id uuid,program_type text,risk_level text,version int not null default 1,status text not null default 'draft' check(status in('draft','review','active','retired')),created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_operations_checklist_items(id uuid primary key default gen_random_uuid(),template_id uuid not null references public.angelcare_marketplace_operations_checklist_templates(id) on delete cascade,item_key text not null,title_fr text not null,instructions_fr text,response_type text not null,required boolean not null default true,critical boolean not null default false,evidence_required boolean not null default false,sort_order int not null default 0,unique(template_id,item_key));
create table if not exists public.angelcare_marketplace_operations_checklist_runs(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.angelcare_marketplace_operations_missions(id),template_id uuid not null references public.angelcare_marketplace_operations_checklist_templates(id),status text not null default 'not_started' check(status in('not_started','in_progress','completed','blocked','review_required')),completion_rate numeric(5,2) not null default 0,critical_failures int not null default 0,started_at timestamptz,completed_at timestamptz,provider_id uuid references public.angelcare_marketplace_provider_profiles(id),territory_id uuid,tenant_id uuid,unique(mission_id,template_id));
create table if not exists public.angelcare_marketplace_operations_checklist_responses(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.angelcare_marketplace_operations_checklist_runs(id) on delete cascade,item_id uuid not null references public.angelcare_marketplace_operations_checklist_items(id),response_status text not null check(response_status in('complete','incomplete','not_applicable','exception','critical_failure')),response_value jsonb not null default '{}',comment text,evidence jsonb not null default '{}',responded_by uuid,responded_at timestamptz not null default now(),unique(run_id,item_id));
create table if not exists public.angelcare_marketplace_operations_mission_reports(id uuid primary key default gen_random_uuid(),mission_id uuid unique not null references public.angelcare_marketplace_operations_missions(id),provider_id uuid not null references public.angelcare_marketplace_provider_profiles(id),current_version int not null default 1,status text not null default 'draft' check(status in('draft','submitted','under_review','correction_required','resubmitted','validated','published','archived')),public_summary text,internal_notes text,structured_report jsonb not null default '{}',submitted_at timestamptz,validated_at timestamptz,validated_by uuid,territory_id uuid,tenant_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_operations_report_versions(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.angelcare_marketplace_operations_mission_reports(id) on delete cascade,version int not null,public_summary text,internal_notes text,structured_report jsonb not null default '{}',submitted_by uuid,submitted_at timestamptz not null default now(),change_reason text,unique(report_id,version));
create table if not exists public.angelcare_marketplace_operations_report_reviews(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.angelcare_marketplace_operations_mission_reports(id),version int not null,decision text not null check(decision in('approve','correction_required','reject')),comments text,reviewer_id uuid not null,reviewed_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_operations_incidents(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('INC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),mission_id uuid not null references public.angelcare_marketplace_operations_missions(id),provider_id uuid references public.angelcare_marketplace_provider_profiles(id),family_account_id uuid references public.angelcare_marketplace_family_accounts(id),organization_id uuid references public.angelcare_marketplace_b2b_organizations(id),territory_id uuid,tenant_id uuid,category text not null,severity text not null check(severity in('low','moderate','high','critical','emergency')),status text not null default 'reported' check(status in('reported','triaged','assigned','under_response','stabilized','investigation','corrective_action','awaiting_validation','resolved','closed','reopened')),occurred_at timestamptz not null,reported_at timestamptz not null default now(),reporter_id uuid,protected_narrative text not null,immediate_actions text[] not null default '{}',safeguarding_flag boolean not null default false,owner_id uuid,response_due_at timestamptz,resolved_at timestamptz,open_flag boolean generated always as (status not in('resolved','closed')) stored,critical_flag boolean generated always as (severity in('critical','emergency') and status not in('resolved','closed')) stored,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_operations_escalations(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.angelcare_marketplace_operations_incidents(id) on delete cascade,escalation_level text not null,recipient_role text not null,recipient_id uuid,deadline_at timestamptz,acknowledged_at timestamptz,resolution_status text not null default 'open',communications jsonb not null default '[]',created_by uuid,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_operations_corrective_actions(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.angelcare_marketplace_operations_incidents(id),action text not null,owner_id uuid,due_at timestamptz,status text not null default 'open',evidence jsonb not null default '{}',validated_by uuid,validated_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_operations_daily_closures(id uuid primary key default gen_random_uuid(),closure_date date not null,territory_id uuid,tenant_id uuid,status text not null default 'draft' check(status in('draft','blocked','ready','approved','reopened')),blockers jsonb not null default '{}',mission_count int not null default 0,supervisor_id uuid,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(closure_date,territory_id,tenant_id));
create table if not exists public.angelcare_marketplace_operations_proof_records(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.angelcare_marketplace_operations_missions(id),proof_type text not null,source_table text not null,source_id uuid not null,evidence_hash text,visibility text not null default 'internal' check(visibility in('internal','family','partner','finance')),created_by uuid,created_at timestamptz not null default now(),unique(mission_id,proof_type,source_id));

create or replace function public.angelcare_marketplace_transition_operations_mission(p_mission_id uuid,p_next_status text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare m public.angelcare_marketplace_operations_missions;allowed boolean:=false;begin select * into m from public.angelcare_marketplace_operations_missions where id=p_mission_id for update;if m.id is null then raise exception 'Mission not found';end if;allowed:=case m.status when 'draft' then p_next_status in('awaiting_authorization','cancelled') when 'awaiting_authorization' then p_next_status in('authorized','draft','cancelled') when 'authorized' then p_next_status in('staffing_required','cancelled','suspended') when 'staffing_required' then p_next_status in('proposed','cancelled','suspended') when 'proposed' then p_next_status in('assigned','staffing_required','cancelled') when 'assigned' then p_next_status in('awaiting_acceptance','staffing_required','cancelled') when 'awaiting_acceptance' then p_next_status in('accepted','staffing_required','cancelled') when 'accepted' then p_next_status in('brief_acknowledged','cancelled','suspended') when 'brief_acknowledged' then p_next_status in('travel_ready','suspended') when 'travel_ready' then p_next_status in('check_in_pending','suspended') when 'check_in_pending' then p_next_status in('in_progress','incident_open','suspended') when 'in_progress' then p_next_status in('incident_open','check_out_pending','suspended') when 'incident_open' then p_next_status in('in_progress','check_out_pending','suspended') when 'check_out_pending' then p_next_status in('report_pending','incident_open') when 'report_pending' then p_next_status in('validation_pending','incident_open') when 'validation_pending' then p_next_status in('correction_required','validated','incident_open') when 'correction_required' then p_next_status in('validation_pending','incident_open') when 'validated' then p_next_status in('payable_handover','closed') when 'payable_handover' then p_next_status='closed' when 'suspended' then p_next_status in('staffing_required','accepted','in_progress','cancelled') else false end;if not allowed then raise exception 'Invalid mission transition % -> %',m.status,p_next_status;end if;if p_next_status='accepted' and not exists(select 1 from public.angelcare_marketplace_operations_mission_assignments where mission_id=m.id and status='accepted') then raise exception 'Provider acceptance is missing';end if;if p_next_status='brief_acknowledged' and not exists(select 1 from public.angelcare_marketplace_operations_brief_acknowledgements where mission_id=m.id) then raise exception 'Brief acknowledgement is missing';end if;if p_next_status='in_progress' and not exists(select 1 from public.angelcare_marketplace_operations_check_events where mission_id=m.id and event_type='check_in') then raise exception 'Check-in evidence is missing';end if;if p_next_status='report_pending' and not exists(select 1 from public.angelcare_marketplace_operations_check_events where mission_id=m.id and event_type='check_out') then raise exception 'Check-out evidence is missing';end if;if p_next_status='validated' and not exists(select 1 from public.angelcare_marketplace_operations_mission_reports where mission_id=m.id and status in('validated','published')) then raise exception 'Validated report is missing';end if;update public.angelcare_marketplace_operations_missions set status=p_next_status,next_action=p_reason,authorized_at=case when p_next_status='authorized' then now() else authorized_at end,validated_at=case when p_next_status='validated' then now() else validated_at end,closed_at=case when p_next_status='closed' then now() else closed_at end,updated_by=p_actor_id,updated_at=now() where id=m.id returning * into m;if p_next_status='payable_handover' then insert into public.angelcare_marketplace_provider_payable_eligibility(provider_id,mission_id,status,checklist,blockers,territory_id,tenant_id) select m.assigned_provider_id,m.id,'eligible',jsonb_build_object('authorized',m.authorized_at is not null,'accepted',exists(select 1 from public.angelcare_marketplace_operations_mission_assignments where mission_id=m.id and status='accepted'),'check_in',exists(select 1 from public.angelcare_marketplace_operations_check_events where mission_id=m.id and event_type='check_in'),'check_out',exists(select 1 from public.angelcare_marketplace_operations_check_events where mission_id=m.id and event_type='check_out'),'report_validated',m.validated_at is not null),'{}',m.territory_id,m.tenant_id where m.assigned_provider_id is not null on conflict(provider_id,mission_id) do update set status='eligible',checklist=excluded.checklist,blockers='{}',updated_at=now();end if;return to_jsonb(m);end$$;
create or replace function public.angelcare_marketplace_generate_assignment_proposals(p_mission_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare m public.angelcare_marketplace_operations_missions;inserted int;begin select * into m from public.angelcare_marketplace_operations_missions where id=p_mission_id;if m.id is null then raise exception 'Mission not found';end if;insert into public.angelcare_marketplace_operations_assignment_proposals(mission_id,provider_id,score,eligibility_snapshot,availability_snapshot,travel_snapshot,conflicts,status,proposed_by) select m.id,p.id,greatest(0,e.score-case when m.operational_zone is not null and not(m.operational_zone=any(p.operational_zones)) then 25 else 0 end),to_jsonb(e),jsonb_build_object('rules',coalesce((select count(*) from public.angelcare_marketplace_provider_availability_rules ar where ar.provider_id=p.id and ar.active),0)),jsonb_build_object('zone',m.operational_zone),case when m.operational_zone is not null and not(m.operational_zone=any(p.operational_zones)) then array['zone_mismatch']::text[] else '{}'::text[] end,'proposed',p_actor_id from public.angelcare_marketplace_provider_profiles p join lateral(select * from public.angelcare_marketplace_provider_operational_eligibility e where e.provider_id=p.id order by e.calculated_at desc limit 1)e on true where e.status in('eligible','eligible_with_restrictions') and (m.territory_id is null or p.territory_id=m.territory_id) and (m.tenant_id is null or p.tenant_id=m.tenant_id) and m.service_type=any(p.service_categories) on conflict do nothing;get diagnostics inserted=row_count;update public.angelcare_marketplace_operations_missions set status=case when inserted>0 then 'proposed' else 'staffing_required' end,updated_at=now() where id=m.id;return jsonb_build_object('mission_id',m.id,'proposals_created',inserted);end$$;
create or replace function public.angelcare_marketplace_decide_assignment_proposal(p_proposal_id uuid,p_decision text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.angelcare_marketplace_operations_assignment_proposals;m public.angelcare_marketplace_operations_missions;e public.angelcare_marketplace_provider_operational_eligibility;a public.angelcare_marketplace_operations_mission_assignments;begin select * into p from public.angelcare_marketplace_operations_assignment_proposals where id=p_proposal_id for update;if p.id is null then raise exception 'Proposal not found';end if;select * into m from public.angelcare_marketplace_operations_missions where id=p.mission_id for update;select * into e from public.angelcare_marketplace_provider_operational_eligibility where provider_id=p.provider_id order by calculated_at desc limit 1;if p_decision='accept' then if e.status not in('eligible','eligible_with_restrictions') or cardinality(p.conflicts)>0 then raise exception 'Provider is not assignable';end if;update public.angelcare_marketplace_operations_assignment_proposals set status='selected',decided_by=p_actor_id,decided_at=now(),decision_reason=p_reason where id=p.id;insert into public.angelcare_marketplace_operations_mission_assignments(mission_id,provider_id,proposal_id,status,assigned_by,territory_id,tenant_id) values(m.id,p.provider_id,p.id,'awaiting_acceptance',p_actor_id,m.territory_id,m.tenant_id) returning * into a;update public.angelcare_marketplace_operations_missions set assigned_provider_id=p.provider_id,status='awaiting_acceptance',updated_by=p_actor_id,updated_at=now() where id=m.id;update public.angelcare_marketplace_operations_assignment_proposals set status='rejected',decided_by=p_actor_id,decided_at=now(),decision_reason='Autre provider sélectionné' where mission_id=m.id and id<>p.id and status='proposed';else update public.angelcare_marketplace_operations_assignment_proposals set status='rejected',decided_by=p_actor_id,decided_at=now(),decision_reason=p_reason where id=p.id;end if;return jsonb_build_object('proposal',to_jsonb(p),'assignment',to_jsonb(a));end$$;
create or replace function public.angelcare_marketplace_record_mission_check_event(p_mission_id uuid,p_event_type text,p_provider_user_id uuid,p_evidence_method text,p_location jsonb,p_device_context jsonb,p_exception_reason text) returns jsonb language plpgsql security definer set search_path=public as $$declare m public.angelcare_marketplace_operations_missions;p public.angelcare_marketplace_provider_profiles;e public.angelcare_marketplace_operations_check_events;begin select * into p from public.angelcare_marketplace_provider_profiles where canonical_app_user_id=p_provider_user_id;if p.id is null then raise exception 'Provider identity not resolved';end if;select * into m from public.angelcare_marketplace_operations_missions where id=p_mission_id and assigned_provider_id=p.id for update;if m.id is null then raise exception 'Provider is not assigned to mission';end if;if p_event_type='check_in' and m.status not in('check_in_pending','travel_ready','incident_open') then raise exception 'Mission is not ready for check-in';end if;if p_event_type='check_out' and m.status not in('in_progress','incident_open','check_out_pending') then raise exception 'Mission is not ready for check-out';end if;insert into public.angelcare_marketplace_operations_check_events(mission_id,provider_id,event_type,evidence_method,location,device_context,exception_reason,review_status,territory_id,tenant_id) values(m.id,p.id,p_event_type,p_evidence_method,coalesce(p_location,'{}'),coalesce(p_device_context,'{}'),p_exception_reason,case when p_exception_reason is null then 'accepted' else 'review_required' end,m.territory_id,m.tenant_id) on conflict(mission_id,provider_id,event_type) do update set event_at=now(),evidence_method=excluded.evidence_method,location=excluded.location,device_context=excluded.device_context,exception_reason=excluded.exception_reason,review_status=excluded.review_status returning * into e;update public.angelcare_marketplace_operations_missions set status=case when p_event_type='check_in' then 'in_progress' else 'report_pending' end,updated_at=now() where id=m.id;return to_jsonb(e);end$$;
create or replace function public.angelcare_marketplace_close_operational_day(p_closure_date date,p_territory_id uuid,p_tenant_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare blockers jsonb;mission_count int;status text;r public.angelcare_marketplace_operations_daily_closures;begin select count(*) into mission_count from public.angelcare_marketplace_operations_missions where mission_date=p_closure_date and (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id);select jsonb_build_object('unassigned',count(*) filter(where status='staffing_required'),'acceptance_missing',count(*) filter(where status='awaiting_acceptance'),'check_in_missing',count(*) filter(where status='check_in_pending'),'check_out_missing',count(*) filter(where status='check_out_pending'),'reports_pending',count(*) filter(where status in('report_pending','validation_pending','correction_required')),'critical_incidents',(select count(*) from public.angelcare_marketplace_operations_incidents where critical_flag and occurred_at::date=p_closure_date)) into blockers from public.angelcare_marketplace_operations_missions where mission_date=p_closure_date and (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id);status:=case when coalesce((blockers->>'unassigned')::int,0)+coalesce((blockers->>'acceptance_missing')::int,0)+coalesce((blockers->>'check_in_missing')::int,0)+coalesce((blockers->>'check_out_missing')::int,0)+coalesce((blockers->>'reports_pending')::int,0)+coalesce((blockers->>'critical_incidents')::int,0)>0 then 'blocked' else 'approved' end;insert into public.angelcare_marketplace_operations_daily_closures(closure_date,territory_id,tenant_id,status,blockers,mission_count,supervisor_id,approved_at) values(p_closure_date,p_territory_id,p_tenant_id,status,blockers,mission_count,p_actor_id,case when status='approved' then now() else null end) on conflict(closure_date,territory_id,tenant_id) do update set status=excluded.status,blockers=excluded.blockers,mission_count=excluded.mission_count,supervisor_id=excluded.supervisor_id,approved_at=excluded.approved_at,updated_at=now() returning * into r;if status='blocked' then raise exception 'Operational closure blocked: %',blockers;end if;return to_jsonb(r);end$$;

insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.operations.view','Voir Operations Command','Operations & Dispatch',false),('marketplace.operations.missions.create','Créer des missions','Operations & Dispatch',true),('marketplace.operations.missions.manage','Gérer les missions','Operations & Dispatch',true),('marketplace.operations.dispatch.manage','Gérer le dispatch','Operations & Dispatch',true),('marketplace.operations.assign','Affecter un provider','Operations & Dispatch',true),('marketplace.operations.reassign','Réaffecter un provider','Operations & Dispatch',true),('marketplace.operations.checklists.manage','Gérer les checklists','Operations & Dispatch',true),('marketplace.operations.reports.review','Réviser les rapports','Operations & Dispatch',true),('marketplace.operations.reports.validate','Valider les rapports','Operations & Dispatch',true),('marketplace.operations.incidents.view','Voir les incidents','Operations & Dispatch',false),('marketplace.operations.incidents.manage','Gérer les incidents','Operations & Dispatch',true),('marketplace.operations.incidents.escalate','Escalader les incidents','Operations & Dispatch',true),('marketplace.operations.closure.approve','Approuver la clôture','Operations & Dispatch',true),('marketplace.operations.proof.export','Exporter les preuves','Operations & Dispatch',true),('marketplace.operations.live.view','Voir les opérations live','Operations & Dispatch',false)
on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.operations.%' on conflict do nothing;
insert into public.angelcare_marketplace_modules(module_key,name,description,route_prefix,module_type,audience,status,enabled,required_permissions,required_dependencies,territory_aware,tenant_aware,locale_aware,health_status,owner_role,introduced_by_mega_zip) values('operations-execution','Operations, Dispatch & Mission Proof','Dispatch, check-in/out, checklists, incidents, validation et payable handover.','/angelcare-marketplace/admin/operations','operating_engine',array['admin','executive','provider','tenant','parent']::text[],'enabled',true,array['marketplace.operations.view']::text[],array['provider-workforce','family-experience','b2b-verticals']::text[],true,true,true,'healthy','operations_manager',18) on conflict(module_key) do update set status='enabled',enabled=true,route_prefix=excluded.route_prefix,required_permissions=excluded.required_permissions,updated_at=now();
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.operations.enabled','Operations Execution','Dispatch et preuve mission gouvernés.',true,'active','Ultra Delivery 4/5 · Original MZ18') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();

